// A type guard to check if a key is a valid Lucide icon name
export function isValidIcon(key: string | undefined): key is keyof typeof LucideIcons {
  if (!key) return false;
  return key in LucideIcons;
}

export const getIcon = (name: string | undefined): LucideIcon => {
    if (isValidIcon(name)) {
        return LucideIcons[name];
    }
    return Component;
}


export type Panel = {
  id: string;
  title: string;
  type: 'editor' | 'media' | 'sound' | '3d';
  content: string; // For editor, or filename for others
  purpose:string; // For AI prompt
  imageId?: string; // For media panels
  icon?: string;
};

export type Tab = {
  id: string;
  name: string;
  panels: Panel[];
  icon?: string;
};

export type Tool = {
  id: string;
  name: string;
  icon: LucideIcon | string;
  layout: Tab[];
};

